function hydrateSave(saved){
  const loaded={...freshState(),...(saved||{}),saveVersion:SAVE_VERSION};
  const renameToday=name=>({"Collier à perles":"Collier de perles","Débardeur":"Débardeur avec manches","Fer a lisser PB&L":"Fer à lisser PB&L","Sèche linge pour nudistes":"Sèche linge pour nudiste","Lot d’équipement pour chasseur":"Lot d’équipements pour chasseur","Lot d'équipement pour chasseur":"Lot d’équipements pour chasseur"})[name]||name;
  ["discoveredItems","collectionDiscoveries","foundUniques"].forEach(key=>{
    if(Array.isArray(loaded[key]))loaded[key]=[...new Set(loaded[key].map(renameToday))];
  });
  loaded.lastDrawnName=renameToday(loaded.lastDrawnName);
  if(saved?.lotFormatVersion!==LOT_FORMAT_VERSION){loaded.lots=[];loaded.lotFormatVersion=LOT_FORMAT_VERSION}
  ["discoveredItems","collectionDiscoveries","foundUniques"].forEach(key=>{
    if(Array.isArray(loaded[key]))loaded[key]=[...new Set(loaded[key].map(name=>name==="Game Boy Color"?"Console portable":name==="Slip de bain Tina Arena"?"Maillot de bain Tina Arena":name))];
  });
  if(loaded.lastDrawnName==="Game Boy Color")loaded.lastDrawnName="Console portable";
  if(loaded.lastDrawnName==="Slip de bain Tina Arena")loaded.lastDrawnName="Maillot de bain Tina Arena";
  ["inventory","showcase"].forEach(zone=>{
    loaded[zone]=Array.isArray(loaded[zone])?loaded[zone]:[];
    loaded[zone]=loaded[zone].map(item=>{
      item={...item,name:renameToday(item.name)};
      if(item.name==="Slip de bain Tina Arena"||item.image?.endsWith("/slip-bain-tina-arena.png")){
        item={...item,name:"Maillot de bain Tina Arena",image:"assets/objects/maillot-bain-tina-arena.png",cat:"Vêtements"};
      }
      if(item.name==="Game Boy Color"||item.image?.endsWith("/game-boy-color.png")){
        item={...item,name:"Console portable"};
        delete item.model;delete item.nativeModel;delete item.true3D;
      }
      // Merge the retired 12-pencil variant without losing owned items or their value.
      if(item.name==="Lot de 12 crayons de couleurs"||item.image?.endsWith("/crayons.png")){
        item={...item,name:"Lot de 32 crayons de couleurs",image:"assets/objects/lot-crayons-couleurs.png",collection:"rentree-2026"};
      }
      const source=ITEMS.find(x=>(x.uniqueKey&&x.uniqueKey===item.uniqueKey)||x.name===item.name);
      return source?{...item,rarity:source.rarity,...(source.image?{image:source.image}:{}),...(source.model?{model:source.model}:{}),...(source.nativeModel?{nativeModel:source.nativeModel}:{}),...(source.true3D?{true3D:true}:{})}:item
    })
  });
  if(loaded.showcase.length>SHOWCASE_LIMIT)loaded.inventory.push(...loaded.showcase.splice(SHOWCASE_LIMIT));
  loaded.badges=Array.isArray(loaded.badges)?loaded.badges:[];
  loaded.badgeUnlocks=Array.isArray(loaded.badgeUnlocks)?loaded.badgeUnlocks:[];
  const owned=[...loaded.inventory,...loaded.showcase].map(item=>item.name);
  const ownedCollectionItems=ITEMS.filter(item=>owned.includes(item.name)&&(item.collection||item.collections?.length)).map(item=>item.name);
  loaded.collectionDiscoveries=[...new Set([...(Array.isArray(loaded.collectionDiscoveries)?loaded.collectionDiscoveries:[]),...ownedCollectionItems])];
  const legacyIcons=Array.isArray(loaded.found)?loaded.found:[],legacyNames=ITEMS.filter(item=>legacyIcons.includes(item.icon)).map(item=>item.name);
  loaded.discoveredItems=[...new Set([...(Array.isArray(loaded.discoveredItems)?loaded.discoveredItems:[]),...owned,...legacyNames])];
  return loaded
}
function load(){try{const saved=JSON.parse(localStorage.getItem(SAVE_KEY));return saved?hydrateSave(saved):freshState()}catch{return freshState()}}
function openSaveDb(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(new Error("IndexedDB indisponible"));const request=indexedDB.open(SAVE_DB,1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains(SAVE_STORE))request.result.createObjectStore(SAVE_STORE)};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function writeBackup(snapshot){try{const db=await openSaveDb(),transaction=db.transaction(SAVE_STORE,"readwrite");transaction.objectStore(SAVE_STORE).put(snapshot,"main");await new Promise((resolve,reject)=>{transaction.oncomplete=resolve;transaction.onerror=()=>reject(transaction.error);transaction.onabort=()=>reject(transaction.error)});db.close()}catch{}}
async function readBackup(){try{const db=await openSaveDb(),transaction=db.transaction(SAVE_STORE,"readonly"),request=transaction.objectStore(SAVE_STORE).get("main");const result=await new Promise((resolve,reject)=>{request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});db.close();return result}catch{return null}}
function save(){checkAchievements();renderAchievements();state.savedAt=Date.now();state.saveVersion=SAVE_VERSION;const snapshot=JSON.parse(JSON.stringify(state));try{localStorage.setItem(SAVE_KEY,JSON.stringify(snapshot))}catch{}writeBackup(snapshot)}
