function rand(a,b){return Math.floor(Math.random()*(b-a+1))+a}
function randFloat(a,b){return a+Math.random()*(b-a)}
function level(){return Math.floor(state.xp/100)+1}
function money(n){return Number(n).toLocaleString("fr-FR",{minimumFractionDigits:Number.isInteger(Number(n))?0:2,maximumFractionDigits:2})+" $"}
function thumbFor(image){return image?.startsWith("assets/objects/")?image.replace("assets/objects/","assets/object-thumbs/").replace(/\.png$/i,".webp"):image}
function relief3D(i){
  const layers=Array.from({length:15},(_,n)=>`<img class="relief-layer" style="--depth:${n-7}" src="${i.image}?v=relief1" alt="" draggable="false">`).join("");
  return `<div class="relief-3d" role="img" aria-label="Objet 3D : ${i.name}">${layers}<img class="relief-face" src="${i.image}?v=relief1" alt="${i.name}" draggable="false"><span class="relief-shine"></span></div>`;
}
function objectVisual(i,context="card"){
  const definition=ITEMS.find(x=>x.name===i.name);
  const source=i.nativeModel||definition?.nativeModel;
  const legacy=i.model||definition?.model;
  const native=source||(legacy?`assets/models/native/${legacy.split('/').pop()}`:null);
  const approvedTrue3D=Boolean(definition?.true3D);
  const displayImage=context==="reveal"?i.image:thumbFor(i.image);
  const nativeViewer=()=>{const spin=context==="reveal"?"":"auto-rotate auto-rotate-delay=\"0\" rotation-per-second=\"11deg\"",poster=context==="reveal"?"":`poster="${displayImage}"`,loading=context==="reveal"?"eager":"lazy";return `<model-viewer class="true-3d-model native-3d-${context}" src="${native}?v=pbr3" ${poster} alt="Modèle 3D complet de ${i.name}" camera-controls loading="${loading}" reveal="auto" ${spin} touch-action="none" interaction-prompt="none" shadow-intensity="1.8" shadow-softness=".88" exposure="1.2" tone-mapping="commerce" environment-image="neutral" camera-orbit="25deg 74deg auto" field-of-view="30deg"></model-viewer>`};
  // Les modèles WebGL sont réservés à l'inspection en grand. Les cartes et la
  // vitrine utilisent les vignettes HD afin de ne pas créer plusieurs scènes GPU.
  if(approvedTrue3D&&native&&context==="reveal")return nativeViewer();
  if(context==="scene"&&displayImage)return `<img class="object-image hd-object-image scene-object-image" src="${displayImage}?v=thumb1" alt="${i.name}" loading="lazy" decoding="async" draggable="false">`;
  if(USE_HD_OBJECT_IMAGES&&displayImage)return `<img class="object-image hd-object-image ${context}-object-image" src="${displayImage}?v=${context==="reveal"?"photo6":"thumb1"}" alt="${i.name}" loading="${context==="reveal"?"eager":"lazy"}" decoding="async" ${context==="reveal"?'fetchpriority="high"':""} draggable="false">`;
  if(native)return nativeViewer();
  if(context==="reveal"&&i.image&&!USE_RECONSTRUCTED_3D)return relief3D(i);
  if(USE_RECONSTRUCTED_3D&&context==="reveal"&&i.model)return `<model-viewer class="true-3d-model" src="${i.model}?v=hq3" poster="${i.image}" alt="Modèle 3D de ${i.name}" camera-controls loading="eager" reveal="auto" touch-action="none" interaction-prompt="none" shadow-intensity="1.4" exposure="1.18" environment-image="neutral" camera-orbit="180deg 90deg auto"></model-viewer>`;
  return i.image?`<img class="object-image ${context}-object-image" src="${i.image}?v=clean1" alt="${i.name}" draggable="false">`:`<span class="emoji-object">${i.icon}</span>`;
}
