function isCollectionDiscovered(item){return state.collectionDiscoveries.includes(item.name)}
function isOwned(item){return [...state.inventory,...state.showcase].some(owned=>(item.uniqueKey&&owned.uniqueKey===item.uniqueKey)||owned.name===item.name)}
function badgeVisual(collection){return collection.badgeImage?`<img src="${collection.badgeImage}" alt="Badge ${collection.badgeName}">`:`<span>${collection.badgeIcon||"◆"}</span>`}
function badgeCelebration(collection,{earned=true}={}){const backdrop=document.createElement("div");backdrop.className="badge-award-backdrop";backdrop.innerHTML=`<div class="badge-award-card" role="alertdialog" aria-modal="true"><div class="badge-rays"></div><div class="badge-medallion">${badgeVisual(collection)}</div><p>${earned?"NOUVEAU BADGE REMPORTÉ":"BADGE DE COLLECTION"}</p><h3>${collection.badgeName}</h3><small>Collection ${collection.name}</small><button class="primary" data-badge-close>Fermer</button></div>${Array.from({length:24},(_,i)=>`<i style="--i:${i}">✦</i>`).join("")}`;document.body.appendChild(backdrop);requestAnimationFrame(()=>backdrop.classList.add("show"));const close=()=>{backdrop.classList.remove("show");setTimeout(()=>backdrop.remove(),250)};backdrop.querySelector("[data-badge-close]").onclick=close;backdrop.onclick=e=>{if(e.target===backdrop)close()};beep(784,.18);setTimeout(()=>beep(1046,.25),130)}
function isCollectionComplete(collection){const items=collectionItems(collection.key),required=collection.plannedSlots||items.length;return Boolean(collection.ready&&items.length>=required&&items.every(isOwned)&&items.every(isCollectionDiscovered))}
function pendingBadgeCollections(){return COLLECTIONS.filter(collection=>!state.badges.includes(collection.badgeKey)&&state.badgeUnlocks.includes(collection.badgeKey))}
function checkCollectionBadges(){let changed=false;for(const collection of COLLECTIONS){if(!state.badges.includes(collection.badgeKey)&&!state.badgeUnlocks.includes(collection.badgeKey)&&isCollectionComplete(collection)){state.badgeUnlocks.push(collection.badgeKey);changed=true}}if(changed)save();renderBadges()}
function claimBadge(key){const collection=COLLECTIONS.find(candidate=>candidate.badgeKey===key);if(!collection||state.badges.includes(key)||!state.badgeUnlocks.includes(key))return;state.badges.push(key);save();updateAll();badgeCelebration(collection)}

function parcelStory(){const country=PARCEL_ORIGINS[rand(0,PARCEL_ORIGINS.length-1)],hub=PARCEL_HUBS[rand(0,PARCEL_HUBS.length-1)],platform=PARCEL_PLATFORMS[rand(0,PARCEL_PLATFORMS.length-1)],days=rand(12,240);return {name:`Provenance : ${country}`,desc:`Égaré depuis ${days} jours après son passage par ${hub}. Expédition issue de la plateforme ${platform}.`}}
function createLot(type,id=Date.now()+Math.random()){return {id,tier:type.tier,...parcelStory(),price:rand(...type.price),image:PARCEL_IMAGE}}
