function normalizeRarity(r){return ({normal:"sans-rarete",commun:"courant",inhabituel:"peu-commun","épique":"rare","légendaire":"legendaire",legendaire:"legendaire","sans-rarete":"sans-rarete",courant:"courant","peu-commun":"peu-commun",rare:"rare",exceptionnel:"exceptionnel",unique:"unique"})[r]||"sans-rarete"}
function rarityInfo(key){return RARITIES.find(r=>r.key===normalizeRarity(key))||RARITIES[0]}
function reputationLevel(){return [...REPUTATION_LEVELS].reverse().find(level=>state.reputation>=level.min)||REPUTATION_LEVELS[0]}
