function renderBadges(){const root=$("#badgesGrid"),empty=$("#emptyBadges");if(!root)return;const earned=COLLECTIONS.filter(collection=>state.badges.includes(collection.badgeKey)),pending=pendingBadgeCollections();root.innerHTML=[...pending.map(collection=>`<article class="badge-card badge-pending"><div class="badge-medallion">${badgeVisual(collection)}</div><p>COLLECTION ${collection.name.toUpperCase()}</p><h3>${collection.badgeName}</h3><small>Badge prêt à être obtenu</small><button class="primary claim-badge" data-claim-badge="${collection.badgeKey}">Obtenir mon badge</button></article>`),...earned.map(collection=>`<button class="badge-card badge-earned" data-view-badge="${collection.badgeKey}" aria-label="Afficher le badge ${collection.badgeName}"><div class="badge-medallion">${badgeVisual(collection)}</div><p>COLLECTION ${collection.name.toUpperCase()}</p><h3>${collection.badgeName}</h3><small>Cliquer pour agrandir</small></button>`)].join("");if(empty)empty.style.display=earned.length||pending.length?"none":"block";$$('[data-claim-badge]').forEach(button=>button.onclick=()=>claimBadge(button.dataset.claimBadge));$$('[data-view-badge]').forEach(button=>button.onclick=()=>{const collection=COLLECTIONS.find(candidate=>candidate.badgeKey===button.dataset.viewBadge);if(collection)badgeCelebration(collection,{earned:false})});const count=$("#badgeCount"),notification=$("#badgeNotification");if(count)count.textContent=earned.length;if(notification){notification.classList.toggle("show",pending.length>0);notification.textContent=pending.length||""}}
