function renderLeaderboard(){const bots=[{n:"MayaDeals",sales:4820,showcase:2760,r:98,a:"🦊"},{n:"LeChineur",sales:3250,showcase:6140,r:76,a:"🧔"},{n:"PixelBroc",sales:2140,showcase:4380,r:61,a:"🤖"},{n:"MamieCash",sales:1380,showcase:7950,r:44,a:"👵"},{n:"CartonMax",sales:740,showcase:1120,r:27,a:"🐻"}],player={n:"Toi",sales:state.totalSales,showcase:state.showcase.reduce((s,i)=>s+i.value,0),r:state.reputation,a:"👑",player:true};const list=[...bots,player].sort((a,b)=>b[activeRanking]-a[activeRanking]);$("#leaderboardList").innerHTML=list.map((x,i)=>`<div class="leader-row ${x.player?"player":""}"><span class="rank">#${i+1}</span><div class="avatar"><i>${x.a}</i><b>${x.n}</b>${activeRanking==="showcase"&&x.player?`<small>${state.showcase.length} objet${state.showcase.length>1?"s":""}</small>`:""}</div><span class="leader-sales">${money(x[activeRanking])}</span><span class="leader-rep">${activeRanking==="sales"?x.r+" réputation":"valeur exposée"}</span></div>`).join("");$("#rankingCaption").textContent=activeRanking==="sales"?"Chiffre d’affaires cumulé de la saison":"Valeur estimée des objets actuellement exposés";$$('[data-ranking]').forEach(b=>b.classList.toggle("active",b.dataset.ranking===activeRanking))}
function renderMoonCounter(){const earthCircumferenceMeters=40075000,cartonHeight=.4,opened=state.cartonsOpened||0,travelled=opened*cartonHeight,remainingKm=Math.max(0,(earthCircumferenceMeters-travelled)/1000),progress=Math.min(100,travelled/earthCircumferenceMeters*100),visibleProgress=opened?Math.max(.8,progress):0;const count=$("#cartonsOpened"),travel=$("#moonTravelled"),percent=$("#moonPercent"),remaining=$("#moonRemaining"),bar=$("#moonProgress"),parcel=$("#moonParcel");if(count)count.textContent=opened.toLocaleString("fr-FR");if(travel)travel.textContent=travelled.toLocaleString("fr-FR",{minimumFractionDigits:Number.isInteger(travelled)?0:1,maximumFractionDigits:1});if(percent)percent.textContent=progress.toLocaleString("fr-FR",{minimumFractionDigits:progress<.01?8:2,maximumFractionDigits:progress<.01?8:2});if(remaining)remaining.textContent=remainingKm.toLocaleString("fr-FR",{maximumFractionDigits:1});if(bar)bar.style.width=`${visibleProgress}%`;if(parcel)parcel.style.left=`${Math.min(97,visibleProgress)}%`}
