const initObjectInspectorLegacy=initObjectInspector;
initObjectInspector=function(){const el=$("#objectInspector"),viewer=el?.querySelector("model-viewer");if(!el||!viewer)return initObjectInspectorLegacy();el.classList.add("has-true-3d");const hint=el.querySelector(".drag-hint");if(hint)hint.textContent="↔ MAINTIENS LE CLIC GAUCHE ET DÉPLACE LA SOURIS";let held=false,startX=0,startY=0,yaw=180,pitch=90;const draw=()=>viewer.setAttribute("camera-orbit",`${yaw}deg ${pitch}deg auto`);el.onpointerdown=e=>{if(e.pointerType==="mouse"&&e.button!==0)return;held=true;startX=e.clientX;startY=e.clientY;el.setPointerCapture(e.pointerId);el.classList.add("held");e.preventDefault()};el.onpointermove=e=>{if(!held)return;yaw=Math.max(105,Math.min(255,yaw+(e.clientX-startX)*.55));pitch=Math.max(35,Math.min(135,pitch+(e.clientY-startY)*.4));startX=e.clientX;startY=e.clientY;draw();e.preventDefault()};const release=e=>{held=false;el.classList.remove("held");if(e.pointerId!==undefined&&el.hasPointerCapture(e.pointerId))el.releasePointerCapture(e.pointerId)};el.onpointerup=release;el.onpointercancel=release;el.onlostpointercapture=()=>{held=false;el.classList.remove("held")};el.oncontextmenu=e=>e.preventDefault();el.onwheel=e=>e.preventDefault();draw()};

// Contrôleur final : respecte l'orientation frontale déclarée sur le modèle.
initObjectInspector=function(){
  const el=$("#objectInspector"),viewer=el?.querySelector("model-viewer");
  if(!el||!viewer)return initObjectInspectorLegacy();
  el.classList.add("has-true-3d");
  const hint=el.querySelector(".drag-hint");
  if(hint)hint.textContent="↔ MAINTIENS LE CLIC GAUCHE ET DÉPLACE LA SOURIS";
  const orbit=viewer.getAttribute("camera-orbit")||"25deg 74deg auto";
  let held=false,startX=0,startY=0,yaw=parseFloat(orbit)||25,pitch=parseFloat(orbit.split(/\s+/)[1])||74;
  const draw=()=>viewer.setAttribute("camera-orbit",`${yaw}deg ${pitch}deg auto`);
  el.onpointerdown=e=>{if(e.pointerType==="mouse"&&e.button!==0)return;held=true;startX=e.clientX;startY=e.clientY;el.setPointerCapture(e.pointerId);el.classList.add("held");e.preventDefault()};
  el.onpointermove=e=>{if(!held)return;yaw+=(e.clientX-startX)*.55;pitch=Math.max(20,Math.min(150,pitch+(e.clientY-startY)*.4));startX=e.clientX;startY=e.clientY;draw();e.preventDefault()};
  const release=e=>{held=false;el.classList.remove("held");if(e.pointerId!==undefined&&el.hasPointerCapture(e.pointerId))el.releasePointerCapture(e.pointerId)};
  el.onpointerup=release;el.onpointercancel=release;el.onlostpointercapture=()=>{held=false;el.classList.remove("held")};el.oncontextmenu=e=>e.preventDefault();el.onwheel=e=>e.preventDefault();draw();
};

